package com.taemoi.project.services;
import static org.junit.jupiter.api.Assertions.*; import java.awt.image.BufferedImage; import java.io.*; import java.nio.file.*; import java.time.LocalDate; import java.util.stream.IntStream; import javax.imageio.ImageIO; import org.apache.pdfbox.pdmodel.PDDocument; import org.apache.pdfbox.rendering.PDFRenderer; import org.apache.pdfbox.text.PDFTextStripper; import org.junit.jupiter.api.Test; import com.taemoi.project.entities.*; import com.taemoi.project.services.impl.PDFServiceImpl;
class PreinscripcionPdfTest {
 @Test void generaPdfValidoParaLosCuatroDeportes() throws Exception {Path dir=Path.of("target","preinscripcion-pdf");Files.createDirectories(dir);for(Deporte d:Deporte.values()){Preinscripcion p=solicitud(d);byte[] pdf=new PDFServiceImpl().generarPreinscripcionFirmada(p);assertTrue(pdf.length>1000);assertEquals("%PDF",new String(pdf,0,4));Files.write(dir.resolve(d.name().toLowerCase()+".pdf"),pdf);try(var doc=PDDocument.load(pdf)){assertTrue(doc.getNumberOfPages()>=1);BufferedImage preview=new PDFRenderer(doc).renderImageWithDPI(0,110);ImageIO.write(preview,"png",dir.resolve(d.name().toLowerCase()+".png").toFile());}}}
 @Test void normasLargasNoDejanHuecoDespuesDelConsentimiento() throws Exception {Preinscripcion p=solicitud(Deporte.TAEKWONDO);String normas=IntStream.rangeClosed(1,24).mapToObj(i->"\"Norma "+i+": texto de prueba suficientemente largo para comprobar correctamente la paginación del documento.\"").reduce((a,b)->a+","+b).orElseThrow();p.getPlantilla().setContenido("{\"normas\":["+normas+"]}");byte[] pdf=new PDFServiceImpl().generarPreinscripcionFirmada(p);Path dir=Path.of("target","preinscripcion-pdf");Files.createDirectories(dir);Files.write(dir.resolve("taekwondo-normas-largas.pdf"),pdf);try(var doc=PDDocument.load(pdf)){PDFTextStripper text=new PDFTextStripper();PDFRenderer renderer=new PDFRenderer(doc);boolean comprobado=false;for(int pagina=1;pagina<=doc.getNumberOfPages();pagina++){ImageIO.write(renderer.renderImageWithDPI(pagina-1,110),"png",dir.resolve("taekwondo-normas-largas-"+pagina+".png").toFile());text.setStartPage(pagina);text.setEndPage(pagina);String contenido=text.getText(doc);if(contenido.contains("Consentimiento fotográfico")){assertTrue(contenido.contains("Normas de la escuela"),"Las normas deben comenzar sin dejar el resto de la página vacío");comprobado=true;}}assertTrue(comprobado);}}
 private Preinscripcion solicitud(Deporte d)throws Exception{Preinscripcion p=new Preinscripcion();p.setReferencia("PRE-2026-TEST");p.setTemporada("2026-2027");p.setDeporte(d);p.setNombre("María");p.setApellidos("Muñoz Pérez");p.setDni("12345678Z");p.setFechaNacimiento(LocalDate.of(2000,1,1));p.setDireccion("Calle Real 1, Umbrete");p.setTelefono("600000000");p.setEmail("maria@example.com");p.setAceptacionNormas(true);p.setConsentimientoFotografico(false);p.setFirmanteNombre("María Muñoz");p.setTurnoSnapshot("Adultos · lunes · 19:00-20:00");PlantillaPreinscripcion t=new PlantillaPreinscripcion();t.setContenido("{\"normas\":[\"Primera norma.\",\"Segunda norma.\"]}");p.setPlantilla(t);BufferedImage image=new BufferedImage(80,30,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();g.setColor(java.awt.Color.WHITE);g.fillRect(0,0,80,30);g.setColor(java.awt.Color.BLUE);g.drawLine(5,20,70,8);g.dispose();ByteArrayOutputStream out=new ByteArrayOutputStream();ImageIO.write(image,"png",out);p.setFirma(out.toByteArray());return p;}
}
